import{z as i,x as s,o as e,c as d,q as n,j as r,D as a,d as A,s as B,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"内生技术的增长模型","description":"","frontmatter":{"title":"内生技术的增长模型","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gd-endogenous-growth-deep.md","filePath":"econ/gd-endogenous-growth-deep.md","lastUpdated":1791063341000}'),p={name:"econ/gd-endogenous-growth-deep.md"};function h(c,E,g,m,u,D){const t=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=n('<h1 id="内生技术的增长模型" tabindex="-1">内生技术的增长模型 <a class="header-anchor" href="#内生技术的增长模型" aria-label="Permalink to &quot;内生技术的增长模型&quot;">​</a></h1><div class="epigraph"><p>技术不是天上掉下来的残差，而是有人花真金白银买来的产出；创意之所以能定价，是因为它附带一份垄断权。</p><footer>—— 据 Romer, &quot;Endogenous Technological Change&quot;, JPE 1990 整理</footer></div><p><a href="/econ/ur-map">上一课</a>把城市与区域收束：Rosen–Roback 三价拉平效用、价差就是宜居性的价格，聚集增益被住房约束截断即是空间错配。空间差距之外，是增长理论的老问题——人均收入几十倍的差距从哪来，为什么不闭合。本课程进入增长与发展的深钻层，第一课把技术的来源内生化。主干课的<a href="/econ/endogenous-growth">内生增长</a>给出了「知识非竞争时增长可内生」的直觉，<a href="/econ/ak-variety-schumpeter">AK、种类与熊彼特</a>把机制分成三分；本课不再分类，而是把其中两支完整解出，把「均衡增长率」变成一个能写公式、能被数据打脸的对象。后课默认读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/solow-growth">索洛模型</a>把长期增长率 \\(g\\) 留在外生参数里：政策只能动水平线，动不了斜率。要回答「补贴研发能否永久加速增长」，必须把 \\(A\\) 的生产写成家庭与企业的最优化结果。难点在市场结构：创意若按完全竞争定价，复制的边际成本近乎零，发明者拿不到回报，没有研发；若禁止一切复制，又丢掉创意最要紧的非竞争性。<span class="marginnote">「非竞争性」翻译成大白话：一个苹果只能一个人吃（竞争性），但一份菜谱可以同时被一万个厨房使用而互不妨碍（非竞争性）。正因为不用抢，按边际成本定价的菜谱几乎白送，发明菜谱的人就白忙了——专利垄断是给菜谱标价的拐杖。</span>缺口因此不是再加一层直觉，而是回答「创意的报酬从哪来」——Romer 的答案是让带专利的创意进垄断部门。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型分三层：最终品完全竞争；每种中间品由持专利的垄断者独家生产，垄断租金是创意的报酬；研发部门完全竞争，一份新创意的价格等于它未来租金的现值。创意生产写 \\(\\dot{A}=\\delta L_A A\\)：投入是研究劳动，存量 \\(A\\) 全额溢出，这是「站在肩膀上」的第一代设定。均衡由一个套利条件钉住：一个工人进工厂挣工资、还是进研发挣创意销售份额，二者无差异，\\(w=v\\,\\delta A\\)，而创意价值 \\(v\\) 是利润流按 \\(r-g_A\\) 贴现的现值。垄断定价把价格钉在边际成本之上：\\(p=mc/\\alpha\\gt mc\\)，毛利率给出每期利润 \\(\\pi\\)。解出的平衡增长路径上 \\(g_A=g_C=g_Y\\)，且 \\(g\\) 随研发劳动占比上升：增长被压进了激励结构里。</p>',7)),(e(),r(l,null,{default:a(()=>[B(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E7%A0%94%E5%8F%91%E5%8A%B3%E5%8A%A8%22%5D%20--%3E%20IDEA%5B%22%E6%96%B0%E5%88%9B%E6%84%8F%EF%BC%9A%E5%93%81%E7%A7%8D%E6%89%A9%E5%BC%A0%22%5D%0A%20%20IDEA%20--%3E%20MON%5B%22%E4%B8%93%E5%88%A9%E5%9E%84%E6%96%AD%E4%B8%AD%E9%97%B4%E5%93%81%22%5D%0A%20%20MON%20--%3E%20RENT%5B%22%E5%9E%84%E6%96%AD%E7%A7%9F%E9%87%91%22%5D%0A%20%20RENT%20--%3E%20VALUE%5B%22%E5%88%9B%E6%84%8F%E7%8E%B0%E5%80%BC%22%5D%0A%20%20VALUE%20--%3E%20ARB%7B%22%E7%A0%94%E5%8F%91%E5%A5%97%E5%88%A9%EF%BC%9A%E5%B7%A5%E8%B5%84%20%3D%20%E4%BB%B7%E5%80%BC%20%C3%97%20%E7%94%9F%E4%BA%A7%E7%8E%87%22%7D%0A%20%20ARB%20--%3E%20RES%0A%20%20RENT%20--%3E%20STEAL%5B%22%E6%96%B0%E5%88%9B%E6%84%8F%E6%91%A7%E6%AF%81%E5%9C%A8%E4%BD%8D%E7%A7%9F%E9%87%91%22%5D%0A%20%20STEAL%20--%3E%20VALUE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=o("h2",{id:"机制",tabindex:"-1"},[A("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=o("p",null,"垄断是特性而非缺陷。定价高于边际成本造成品种偏少的扭曲，但扭曲出来的租金正是研发的燃料；没有租金，套利条件右侧为零，\\(L_A\\) 为零，增长也归零。均衡与最优之间隔着两个方向相反的外部性：站在肩膀上让私人研发低估 \\(A\\) 的溢出，投入偏少；Aghion-Howitt 的创造性破坏给出反方向的机制——创新者的私人收益里没有算「我的新产品毁掉的是在位者的租金」，激励可以过高。主干课「熊彼特下私人研发不必然不足」的断言，生成机制就在这里：均衡增长率由肩膀效应与商业窃取效应的净额决定。",-1)),(e(),r(l,null,{default:a(()=>[B(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E7%A7%81%E4%BA%BA%E7%A0%94%E5%8F%91%E5%86%B3%E7%AD%96%22%5D%20--%3E%20SH%5B%22%E8%82%A9%E8%86%80%E6%95%88%E5%BA%94%3A%20%E5%AD%98%E9%87%8F%20A%20%E5%85%A8%E9%A2%9D%E6%BA%A2%E5%87%BA%22%5D%0A%20%20SH%20--%3E%20LOW%5B%22%E4%BD%8E%E4%BC%B0%E7%A4%BE%E4%BC%9A%E6%94%B6%E7%9B%8A%20%E2%86%92%20%E6%8A%95%E5%85%A5%E5%81%8F%E5%B0%91%22%5D%0A%20%20INV%20--%3E%20ST%5B%22%E7%AA%83%E5%8F%96%E6%95%88%E5%BA%94%3A%20%E6%96%B0%E5%93%81%E6%AF%81%E5%9C%A8%E4%BD%8D%E7%A7%9F%E9%87%91%22%5D%0A%20%20ST%20--%3E%20HIGH%5B%22%E7%A7%81%E4%BA%BA%E6%94%B6%E7%9B%8A%E5%90%AB%E6%AF%81%E4%BA%BA%E7%A7%9F%E9%87%91%20%E2%86%92%20%E6%BF%80%E5%8A%B1%E5%81%8F%E9%AB%98%22%5D%0A%20%20LOW%20--%3E%20NET%7B%22%E5%87%80%E9%A2%9D%3A%20%E5%9D%87%E8%A1%A1%20g%20%E5%AF%B9%E6%AF%94%E7%A4%BE%E4%BC%9A%E6%9C%80%E4%BC%98%22%7D%0A%20%20HIGH%20--%3E%20NET%0A%20%20NET%20--%3E%7C%22%E7%A0%94%E5%8F%91%E4%B8%8D%E8%B6%B3%22%7C%20SUB%5B%22%E8%A1%A5%E8%B4%B4%3A%20%E6%8A%AC%E5%A5%97%E5%88%A9%E6%9D%A1%E4%BB%B6%E5%8F%B3%E4%BE%A7%22%5D%0A%20%20NET%20--%3E%7C%22%E6%BF%80%E5%8A%B1%E8%BF%87%E5%BA%A6%22%7C%20TAME%5B%22%E7%A8%80%E9%87%8A%E6%BF%80%E5%8A%B1%E6%88%96%E5%BE%81%E7%A7%9F%E9%87%91%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">套利条件的数字版：熟练工进工厂月薪 5000，进研发的期望回报是创意价值 \\(v\\) 乘生产率 \\(\\delta A\\)。若 \\(\\delta A=0.1\\)（一份研究劳动每年产出 0.1 份新创意），要让他愿意搞研究，每份创意得值 5 万——研发工资与专利租金就是靠这根杠杆互相拉扯。</span>政策含义随之改变：研发补贴改的是套利条件右侧，效果是永久动 \\(g\\) 而不是抬一段水平——这是与<a href="/econ/solow-growth">索洛</a>口径的根本区别，也是值得完整解一遍的原因。</p><p><span class="marginnote">Romer 1990 的中间品定价 \\(p=mc/\\alpha\\)：\\(\\alpha\\) 越小加成越大，扭曲与研发激励是同一个参数的两面。判断补贴规模要解套利条件，不是看预算占比。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>第一代设定 \\(\\phi=1\\) 隐含规模效应：\\(g\\) 与研究人数成比例。美国半个世纪的研发投入涨了数倍而生产率增速平稳，这个预言下一课处理，本课只把靶子立起来。<span class="marginnote">初学者容易以为「研发投入翻倍，增速就翻倍」。这是第一代模型的规模效应预言：\\(g\\) 与研究人数成比例。现实中美国研发投入涨了几倍而生产率增速平稳——钓的人多了，鱼没按比例多，因为重复研究与互相踩踏的抵消要等下一代模型处理。</span>模型里制度没有位置：被征收的风险只能压低 \\(\\delta\\) 或抬高贴现率，<a href="/econ/institutions-acemoglu">制度</a>与<a href="/econ/misallocation-tfp">错配</a>留给后面的课。也不要把「增长率由激励决定」读成跨国差距的解释：<a href="/econ/lucas-paradox">Lucas 悖论</a>指向的水平差距主要是资本深化与错配的账，不是各国 \\(g\\) 的差异——增长模型解释趋势线的斜率，不直接解释几十倍的水平比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>创意的报酬由专利垄断的租金给出；三层市场结构把 \\(A\\) 的生产写进最优化。</li><li>均衡增长率由研发套利条件钉住，研发补贴动的是长期 \\(g\\)，不是水平。</li><li>肩膀效应压低私人研发，商业窃取抬高它；净额决定补贴方向，研发不足不是定理。</li><li>垄断加成既是扭曲也是激励，评价政策要落在套利条件上。</li><li>第一代模型的规模效应与制度的缺席是留给后课的两个缺口。</li><li>出处：Romer, &quot;Endogenous Technological Change&quot;, <em>JPE</em> 1990；Aghion and Howitt, &quot;A Model of Growth through Creative Destruction&quot;, <em>Econometrica</em> 1992。</li></ul>',6))])}const T=i(p,[["render",h]]);export{_ as __pageData,T as default};
